package pl.zagranietyper.service;import org.junit.jupiter.api.Test;import pl.zagranietyper.model.FootballFixtureEventsSnapshot;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FootballEventPlayerResolverTest {private final FootballEventPlayerResolver r=new FootballEventPlayerResolver();private static FootballFixtureEventsSnapshot.Event e(long id,String n){return new FootballFixtureEventsSnapshot.Event(0,1L,"T",id,n,null,null,"Goal","Normal Goal",1,null,null);}@Test void exactInitialSurnameAndNormalizationResolve(){assertEquals(7L,r.resolve("Robert Lewandowski",List.of(e(7,"Robert Lewandowski"))).playerId());assertEquals(7L,r.resolve("R. Lewandowski",List.of(e(7,"Robert Lewandowski"))).playerId());assertEquals(7L,r.resolve("É. Nwanéri",List.of(e(7,"E Nwaneri"))).playerId());}@Test void ambiguousAndFuzzyAreRejected(){assertEquals(FootballEventPlayerResolver.Status.AMBIGUOUS,r.resolve("Silva",List.of(e(1,"Bernardo Silva"),e(2,"Rafa Silva"))).status());assertEquals(FootballEventPlayerResolver.Status.AMBIGUOUS,r.resolve("R Silva",List.of(e(1,"Rafa Silva"),e(2,"Renato Silva"))).status());assertEquals(FootballEventPlayerResolver.Status.UNRESOLVED,r.resolve("Lewandowksi",List.of(e(7,"Robert Lewandowski"))).status());}}
